cpp.setup:
auto* control = new fluent::layout::Card(%PARENT%);
auto* layout = new QVBoxLayout(control);
layout->setContentsMargins(16, 14, 16, 16);
layout->setSpacing(4);
auto* title = new fluent::textfields::Label(QStringLiteral("Release checklist"), control);
title->setFluentTypography(Typography::FontRole::BodyStrong);
auto* subtitle = new fluent::textfields::Label(QStringLiteral("All checks passed 2m ago"), control);
subtitle->setFluentTypography(Typography::FontRole::Caption);
subtitle->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
subtitle->setWordWrap(true);
layout->addWidget(title);
layout->addWidget(subtitle);
